using System; using System.Collections.Generic; using System.Linq; using Avalonia; using Avalonia.Controls; using Avalonia.Layout; using Avalonia.Media; using Kreta.Core; using Kreta.Contexts; public class UserManagementView_e1d9c4a8b7f6439e9a0c2d1b5a3f0e8d : UserControl, IEvolView { private IDirectorContext _context; private ListBox _userListBox; private TextBox _nameTextBox; private ComboBox _roleComboBox; private ComboBox _classComboBox; private List<User> _allUsers = new List<User>(); public string Name => "Felhasználókezelés"; public string Description => "Új felhasználók felvétele, meglévők törlése."; public UserManagementView_e1d9c4a8b7f6439e9a0c2d1b5a3f0e8d() { } public UserManagementView_e1d9c4a8b7f6439e9a0c2d1b5a3f0e8d(IDirectorContext context) { _context = context; Content = CreateView(); LoadAllData(); } public Control CreateView() { var mainGrid = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto,*"), Margin = new Thickness(10) }; var leftPanel = new StackPanel { Spacing = 10, Margin = new Thickness(0, 0, 10, 0) }; leftPanel.Children.Add(new TextBlock { Text = "Felhasználók", FontSize = 18, FontWeight = FontWeight.Bold }); _userListBox = new ListBox { Height = 300 }; leftPanel.Children.Add(_userListBox); var deleteButton = new Button { Content = "Kijelölt felhasználó törlése" }; deleteButton.Click += DeleteUser_Click; leftPanel.Children.Add(deleteButton); Grid.SetColumn(leftPanel, 0); var rightPanel = new StackPanel { Spacing = 10, Margin = new Thickness(10, 0, 0, 0) }; rightPanel.Children.Add(new TextBlock { Text = "Új felhasználó", FontSize = 18, FontWeight = FontWeight.Bold }); rightPanel.Children.Add(new TextBlock { Text = "Név:" }); _nameTextBox = new TextBox { PlaceholderText = "Felhasználó neve" }; rightPanel.Children.Add(_nameTextBox); rightPanel.Children.Add(new TextBlock { Text = "Szerepkör:" }); _roleComboBox = new ComboBox(); _roleComboBox.ItemsSource = Enum.GetValues(typeof(Role)).Cast<Role>().Select(r => r.ToString()).ToList(); rightPanel.Children.Add(_roleComboBox); rightPanel.Children.Add(new TextBlock { Text = "Osztály (diák esetén):" }); _classComboBox = new ComboBox(); rightPanel.Children.Add(_classComboBox); var addButton = new Button { Content = "Felhasználó hozzáadása" }; addButton.Click += AddUser_Click; rightPanel.Children.Add(addButton); Grid.SetColumn(rightPanel, 2); mainGrid.Children.Add(leftPanel); mainGrid.Children.Add(new Border { Background = Brushes.LightGray, Width = 1, [Grid.ColumnProperty] = 1 }); mainGrid.Children.Add(rightPanel); return mainGrid; } private void LoadAllData() { if (_context == null) return; LoadUsers(); LoadClasses(); } private void LoadUsers() { _allUsers = _context.GetAllUsers(); _userListBox.ItemsSource = _allUsers.Select(u => $"{u.Name} ({u.Role}) - Osztály: {u.ClassName ?? "N/A"}").ToList(); } private void LoadClasses() { _classComboBox.ItemsSource = _context.GetAllClasses(); } private void AddUser_Click(object sender, Avalonia.Interactivity.RoutedEventArgs e) { if (string.IsNullOrWhiteSpace(_nameTextBox.Text) || _roleComboBox.SelectedItem == null) return; var newUser = new User { Name = _nameTextBox.Text, Role = (Role)Enum.Parse(typeof(Role), _roleComboBox.SelectedItem.ToString()), ClassName = _classComboBox.SelectedItem as string ?? string.Empty }; _context.CreateUser(newUser); LoadUsers(); _nameTextBox.Text = string.Empty; _roleComboBox.SelectedIndex = -1; _classComboBox.SelectedIndex = -1; } private void DeleteUser_Click(object sender, Avalonia.Interactivity.RoutedEventArgs e) { int selectedIndex = _userListBox.SelectedIndex; if (selectedIndex >= 0 && selectedIndex < _allUsers.Count) { var userToDelete = _allUsers[selectedIndex]; _context.DeleteUser(userToDelete.Id); LoadUsers(); } } }